BEGIN READ ONLY;
SELECT json_build_object('marker_count',(SELECT count(*) FROM academy.identity_session_id_digest_transition WHERE migration_name='0034_identity_session_id_digest'),'session_count',(SELECT count(*) FROM academy.identity_session),'invalid_digest_count',(SELECT count(*) FROM academy.identity_session WHERE id !~ '^[A-Za-z0-9_-]{43}$'),'transaction_count',(SELECT count(*) FROM academy.identity_authorization_transaction),'active_claims',(SELECT count(*) FROM academy.identity_authorization_transaction WHERE claim_expires_at>clock_timestamp()),'legacy_links',(SELECT count(*) FROM academy.identity_authorization_transaction WHERE session_id IS NOT NULL OR completed_at IS NOT NULL OR claim_digest IS NOT NULL),'digest_rpc_count',(SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='academy' AND p.proname IN ('create_identity_session_digest','read_identity_session_digest','revoke_identity_session_digest','claim_identity_authorization_transaction_digest','finalize_identity_authorization_transaction_digest')),'runtime_digest_grants',(SELECT bool_and(has_function_privilege('academy_runtime',p.oid,'EXECUTE')) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='academy' AND p.proname IN ('create_identity_session_digest','read_identity_session_digest','revoke_identity_session_digest','claim_identity_authorization_transaction_digest','finalize_identity_authorization_transaction_digest')));
ROLLBACK;
